import{_ as e,o as l,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-05-09 -- Ceph Performance meeting","description":"","frontmatter":{"title":"2019-05-09 -- Ceph Performance meeting","date":"2019-05-09T00:00:00.000Z","updated":"2019-05-28T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","技术讨论","社区动态"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-05-09_-_-_Ceph_Performance_meeting.md","filePath":"posts/2019/2019-05-09_-_-_Ceph_Performance_meeting.md","lastUpdated":1780460162000}'),i={name:"posts/2019/2019-05-09_-_-_Ceph_Performance_meeting.md"};function o(n,a,s,h,p,d){return l(),t("div",null,[...a[0]||(a[0]=[r('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间" tabindex="-1">会议时间 <a class="header-anchor" href="#会议时间" aria-label="Permalink to &quot;会议时间&quot;">​</a></h4><p>[会议时间]</p><h4 id="会议地点" tabindex="-1">会议地点 <a class="header-anchor" href="#会议地点" aria-label="Permalink to &quot;会议地点&quot;">​</a></h4><p>[会议地点]</p><h4 id="参会人员" tabindex="-1">参会人员 <a class="header-anchor" href="#参会人员" aria-label="Permalink to &quot;参会人员&quot;">​</a></h4><p>[列出参会人员姓名]</p><h4 id="会议主题" tabindex="-1">会议主题 <a class="header-anchor" href="#会议主题" aria-label="Permalink to &quot;会议主题&quot;">​</a></h4><p>本周Ceph社区动态及关键议题讨论</p><h4 id="会议内容" tabindex="-1">会议内容 <a class="header-anchor" href="#会议内容" aria-label="Permalink to &quot;会议内容&quot;">​</a></h4><p><strong>1. Ceph社区动态</strong></p><ul><li>本周社区活跃度相对较低，许多成员参加Red Hat峰会，导致活动减少。</li><li>新提交的Pull Request集中在GW管理员功能增强、Seastar性能改进、RBD零拷贝权限、Radix工作、Adam的工作更新、Igor的RocksDB测试、双缓存PR、IOU环工作等方面。</li></ul><p><strong>2. 主要议题讨论</strong></p><p><strong>（1）GW管理员功能增强</strong></p><ul><li>新增PR允许进行无序存储桶列表，提高性能。</li><li>该功能扩展了之前的API，允许应用选择是否进行有序列表。</li></ul><p><strong>（2）Seastar性能改进</strong></p><ul><li>Seastar升级带来性能提升。</li><li>通过C API实现了RBD的零拷贝权限，进一步提升性能。</li></ul><p><strong>（3）Radix工作</strong></p><ul><li>Radix工作部分已关闭，具体原因待定。</li></ul><p><strong>（4）Adam的工作更新</strong></p><ul><li>Adam的工作持续更新，进展良好。</li></ul><p><strong>（5）Igor的RocksDB测试</strong></p><ul><li>Igor的RocksDB测试发现存在一些问题，需要进一步测试和修复。</li></ul><p><strong>（6）双缓存PR</strong></p><ul><li>双缓存PR在测试中表现良好，但存在潜在问题，需要进一步讨论和改进。</li><li>当用户更改存储桶配置时，可能会导致性能问题。</li><li>需要开发工具来帮助迁移和升级。</li></ul><p><strong>（7）IOU环工作</strong></p><ul><li>IOU环工作正在进行中，但仍存在一些问题。</li><li>需要学习IOU环代码，并修复潜在的问题。</li></ul><p><strong>（8）LVM缓存</strong></p><ul><li>LVM缓存测试表明，在特定场景下，使用缓存可以提高性能。</li><li>需要进一步研究在不同工作负载下的性能表现。</li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>继续关注和跟进上述议题，并积极讨论和解决相关问题。</li><li>在Red Hat峰会结束后，恢复正常会议节奏。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>各议题负责人继续推进相关工作。</li><li>定期召开会议，讨论社区动态和关键议题。</li></ul><h4 id="会议总结" tabindex="-1">会议总结 <a class="header-anchor" href="#会议总结" aria-label="Permalink to &quot;会议总结&quot;">​</a></h4><p>本周Ceph社区动态活跃，但受Red Hat峰会等因素影响，活动相对较少。会议讨论了多个关键议题，包括GW管理员功能增强、Seastar性能改进、Radix工作、Adam的工作更新、Igor的RocksDB测试、双缓存PR、IOU环工作、LVM缓存等。会议决定继续关注和推进相关工作，并定期召开会议讨论社区动态和关键议题。</p>',35)])])}const _=e(i,[["render",o]]);export{c as __pageData,_ as default};
